package com.nexttv;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import org.json.*;import java.util.*;
/** Actual real-source concurrent first frames; no fixture videos or preview counter injection. */
public class MultiPreviewInstrumentation extends SettingsAppearanceInstrumentation {
 @Override void key(int k){sendKeyDownUpSync(k);SystemClock.sleep(180);}
 void previewAwait(String label,java.util.concurrent.Callable<Boolean> f)throws Exception{long end=SystemClock.uptimeMillis()+90000;while(SystemClock.uptimeMillis()<end){if(f.call())return;SystemClock.sleep(100);}throw new IllegalStateException(label+" "+preview());}
 JSONObject preview()throws Exception{return diagnostic("Preview");}
 Set<String> ids(JSONArray a)throws Exception{Set<String>s=new HashSet<>();for(int i=0;i<a.length();i++)s.add(a.getString(i));return s;}
 void wheel(float amount){MotionEvent.PointerProperties p=new MotionEvent.PointerProperties();p.id=0;p.toolType=MotionEvent.TOOL_TYPE_MOUSE;MotionEvent.PointerCoords c=new MotionEvent.PointerCoords();c.x=500;c.y=350;c.setAxisValue(MotionEvent.AXIS_VSCROLL,amount);long t=SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(t,t,MotionEvent.ACTION_SCROLL,1,new MotionEvent.PointerProperties[]{p},new MotionEvent.PointerCoords[]{c},0,0,1,1,0,0,InputDevice.SOURCE_MOUSE,0);getUiAutomation().injectInputEvent(e,true);e.recycle();}
 @Override public void onStart(){int code=Activity.RESULT_OK;String result="";try{
  prefs=getTargetContext().getSharedPreferences("nexttv",0);saved=prefs.getAll();prefs.edit().putBoolean("start_live",false).putBoolean("grid_mode",true).putBoolean("channel_previews",false).putBoolean("reduce_motion",false).putBoolean("auto_update",false).putBoolean("auto_update_epg",false).commit();activity=startActivitySync(new Intent().setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await("real home",()->text().contains("CCTV1综合"));int before=preview().getInt("requests");SystemClock.sleep(1500);if(preview().getInt("requests")!=before||preview().getInt("activePlayers")!=0)throw new IllegalStateException("OFF created preview work");pass("OFF creates no preview video requests or players");
  prefs.edit().putBoolean("channel_previews",true).commit();previewAwait("eight actual live preview first frames",()->{JSONObject p=preview();return p.getInt("targetCount")==8&&p.getInt("activePlayers")==8&&p.getInt("renderedPlayers")==8;});JSONObject first=preview();shot("eight-previews");pass("eight visible real channels concurrently render actual first frames: "+first);
  int sessions=first.getInt("sessionStarts");Set<String> original=ids(first.getJSONArray("activeIds"));key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_RIGHT);SystemClock.sleep(1700);JSONObject moved=preview();if(moved.getInt("sessionStarts")!=sessions||!ids(moved.getJSONArray("activeIds")).equals(original))throw new IllegalStateException("Focus changes recreated preview sessions "+moved);pass("same-page focus movement pauses/resumes the same eight streams without decoder recreation");
  wheel(-12);SystemClock.sleep(1400);await("all offscreen previews released",()->{JSONObject p=preview();Set<String>a=ids(p.getJSONArray("activeIds")),t=ids(p.getJSONArray("targetIds"));return !a.isEmpty()&&t.containsAll(a)&&Collections.disjoint(a,original);});shot("scrolled-previews");pass("wheel scrolling releases old offscreen players; cached lazy items do not retain streams: "+preview());
  runOnMainSync(()->activity.moveTaskToBack(true));await("background releases all previews",()->preview().getInt("activePlayers")==0);int backgroundRequests=preview().getInt("requests");SystemClock.sleep(1500);if(preview().getInt("requests")!=backgroundRequests)throw new IllegalStateException("Background restarted preview");runOnMainSync(()->getTargetContext().startActivity(new Intent().setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));await("foreground previews resume",()->preview().getInt("activePlayers")>1);pass("background releases all preview decoders/requests; emulator foreground restoration resumes visible previews");
  prefs.edit().putBoolean("channel_previews",false).commit();await("OFF releases all",()->preview().getInt("activePlayers")==0&&preview().getInt("targetCount")==0);int end=preview().getInt("requests");SystemClock.sleep(2000);if(preview().getInt("requests")!=end)throw new IllegalStateException("OFF restarted requests");pass("OFF after active multi-preview releases every player and stops video work");result="Multi preview "+passed+" groups passed";
 }catch(Throwable e){code=Activity.RESULT_CANCELED;result=android.util.Log.getStackTraceString(e)+"\n"+dump();try{shot("multi-preview-failure");}catch(Exception ignored){}}finally{restore();}Bundle b=new Bundle();b.putString("stream",result);finish(code,b);
 }
}
